insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000482011', '40000000-0000-4000-8000-000000048201', 'Faça primeiro um pequeno registro das grandezas conhecidas e daquilo que a pergunta realmente pede.', 1), ('60000000-0000-4000-8000-000000482012', '40000000-0000-4000-8000-000000048201', 'A área do paralelogramo é o módulo do produto vetorial.', 2), ('60000000-0000-4000-8000-000000482013', '40000000-0000-4000-8000-000000048201', 'Os vetores são perpendiculares, então a área também é o produto dos módulos.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048201', '$A=4$.', 'Trate as coordenadas como informações de posição: alinhar cada eixo antes de operar evita conclusões visuais enganosas. O produto vetorial produz um vetor perpendicular aos dois fatores, com sentido determinado pela regra da mão direita. Seu módulo também mede a área do paralelogramo; o produto misto acrescenta um terceiro vetor e mede volume orientado. A alternativa A coincide com a relação obtida; a alternativa B ($2$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000482011', '40000000-0000-4000-8000-000000048201', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000482012', '40000000-0000-4000-8000-000000048201', 'Calcule o produto', '$u \times v=(0,0,4).$', 2), ('70000000-0000-4000-8000-000000482013', '40000000-0000-4000-8000-000000048201', 'Tome o módulo', '$|u \times v|=4.$', 3), ('70000000-0000-4000-8000-000000482014', '40000000-0000-4000-8000-000000048201', 'Interprete', 'Esse módulo é a área do paralelogramo.', 4), ('70000000-0000-4000-8000-000000482015', '40000000-0000-4000-8000-000000048201', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
