insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000482121', '40000000-0000-4000-8000-000000048212', 'Escreva a relação matemática antes de substituir os valores; isso torna sinais e denominadores mais visíveis.', 1), ('60000000-0000-4000-8000-000000482122', '40000000-0000-4000-8000-000000048212', 'O módulo do produto vetorial fornece a área do paralelogramo.', 2), ('60000000-0000-4000-8000-000000482123', '40000000-0000-4000-8000-000000048212', 'O triângulo ocupa metade do paralelogramo.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048212', '$A=6$.', 'Uma boa conferência separa a ideia geométrica da conta numérica e testa o resultado na relação inicial. O produto vetorial produz um vetor perpendicular aos dois fatores, com sentido determinado pela regra da mão direita. Seu módulo também mede a área do paralelogramo; o produto misto acrescenta um terceiro vetor e mede volume orientado. A alternativa A coincide com a relação obtida; a alternativa B ($12$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
