insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000482331', '40000000-0000-4000-8000-000000048233', 'Ao final, pergunte se o sinal, a direção ou a dimensão do resultado fazem sentido para a situação.', 1), ('60000000-0000-4000-8000-000000482332', '40000000-0000-4000-8000-000000048233', 'Uma direção é obtida ligando um ponto ao outro.', 2), ('60000000-0000-4000-8000-000000482333', '40000000-0000-4000-8000-000000048233', 'Faça B menos A componente a componente.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048233', '$d=(2,5,-2)$.', 'O resultado deve respeitar tanto a definição algébrica quanto a interpretação geométrica do objeto em três dimensões. Uma reta espacial fica determinada por um ponto e um vetor diretor não nulo. A forma paramétrica soma ao ponto um múltiplo real da direção; por isso, substituir o parâmetro ou comparar componentes permite verificar cada resultado sem ambiguidade. A alternativa A coincide com a relação obtida; a alternativa B ($(7,5,-1)$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000482331', '40000000-0000-4000-8000-000000048233', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000482332', '40000000-0000-4000-8000-000000048233', 'Escolha o sentido', '$d=B-A.$', 2), ('70000000-0000-4000-8000-000000482333', '40000000-0000-4000-8000-000000048233', 'Subtraia', '$d=(7,5,-1)-(5,0,1).$', 3), ('70000000-0000-4000-8000-000000482334', '40000000-0000-4000-8000-000000048233', 'Confira', '$A+d=B.$', 4), ('70000000-0000-4000-8000-000000482335', '40000000-0000-4000-8000-000000048233', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
