insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048240', '$t=9$.', 'A resolução fica mais segura quando cada transformação é justificada e o resultado é verificado no enunciado original. Uma reta espacial fica determinada por um ponto e um vetor diretor não nulo. A forma paramétrica soma ao ponto um múltiplo real da direção; por isso, substituir o parâmetro ou comparar componentes permite verificar cada resultado sem ambiguidade. A alternativa A coincide com a relação obtida; a alternativa B ($t=-9$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
