insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000482491', '40000000-0000-4000-8000-000000048249', 'Não tente calcular tudo de uma vez: destaque primeiro a propriedade que caracteriza o problema.', 1), ('60000000-0000-4000-8000-000000482492', '40000000-0000-4000-8000-000000048249', 'No plano xy, a coordenada z é zero.', 2), ('60000000-0000-4000-8000-000000482493', '40000000-0000-4000-8000-000000048249', 'Use a terceira equação para encontrar t e depois calcule x e y.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048249', '$(14,-6,0)$.', 'A notação compacta não substitui o raciocínio: identificar o tipo de objeto é o passo que determina qual fórmula usar. Uma reta espacial fica determinada por um ponto e um vetor diretor não nulo. A forma paramétrica soma ao ponto um múltiplo real da direção; por isso, substituir o parâmetro ou comparar componentes permite verificar cada resultado sem ambiguidade. A alternativa A coincide com a relação obtida; a alternativa B ($(7,1,14)$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
